const canvas = document.getElementById("map");
const context = canvas.getContext("2d");
const statusEl = document.getElementById("status");
const sessionLabel = document.getElementById("sessionLabel");
const pipButton = document.getElementById("pipButton");
const pipVideo = document.getElementById("pipVideo");
const pathParts = window.location.pathname.split("/").filter(Boolean);
const lastPart = pathParts[pathParts.length - 1] || "";
const searchParams = new URLSearchParams(window.location.search);
const sessionId = searchParams.get("code") || searchParams.get("m") || (lastPart && !lastPart.includes(".html") ? lastPart : "") || "TEST88";
const token = searchParams.get("t") || "";
const debugEnabled = searchParams.get("debug") === "1" || searchParams.get("debug") === "true";
const calibrationPanel = document.getElementById("calibrationPanel");
const calibrationOutput = document.getElementById("calibrationOutput");
const stepSizeEl = document.getElementById("stepSize");
const markerScaleXInput = document.getElementById("markerScaleX");
const markerScaleYInput = document.getElementById("markerScaleY");
const anchorPlayerSelect = document.getElementById("anchorPlayerSelect");
const anchorStatusEl = document.getElementById("anchorStatus");
const mapAssetVersion = "frontendsecure1";
const mapImageSources = {
  1: `./assets/minimap.png?v=${mapAssetVersion}`,
  2: `./assets/minimap.png?v=${mapAssetVersion}`
};
const minimapImages = {};
const minimapImageReady = {};
const heroIconBaseUrl = "./assets/hero-icons";
const heroIconCache = new Map();

const defaultCalibration = Object.freeze({
  left: 0,
  top: 0,
  right: 1,
  bottom: 1,
  imageScale: 1,
  offsetX: 0,
  offsetY: 0,
  scaleX: 1,
  scaleY: 1
});
const calibrationStorageKey = "share-map-calibration-v1";
const anchorStorageKey = "share-map-anchors-v2";
const defaultAnchors = Object.freeze([
  Object.freeze({ worldX: -25.79463, worldZ: 1.95444, u: 0.27524, v: 0.47944, team: 1, heroId: 0, createdAt: 1783338217265 }),
  Object.freeze({ worldX: -18.8965, worldZ: 22.81228, u: 0.32915, v: 0.29214, team: 1, heroId: 0, createdAt: 1783338234661 }),
  Object.freeze({ worldX: -3.77107, worldZ: 30.99216, u: 0.47168, v: 0.20443, team: 1, heroId: 0, createdAt: 1783338244082 }),
  Object.freeze({ worldX: 3.60905, worldZ: -32.85885, u: 0.53655, v: 0.79283, team: 1, heroId: 0, createdAt: 1783338338903 }),
  Object.freeze({ worldX: -53.13168, worldZ: 3.53316, u: 0.01576, v: 0.49497, team: 1, heroId: 0, createdAt: 1783338410688 }),
  Object.freeze({ worldX: 53.86124, worldZ: 52.05254, u: 0.98515, v: 0.01804, team: 1, heroId: 0, createdAt: 1783338474234 }),
  Object.freeze({ worldX: 22.88808, worldZ: -50.13942, u: 0.69004, v: 0.96642, team: 1, heroId: 0, createdAt: 1783338553000 }),
  Object.freeze({ worldX: 50.2184, worldZ: -23.37335, u: 0.9614, v: 0.7106, team: 1, heroId: 0, createdAt: 1783338571916 })
]);
const defaultAnchorTransform = Object.freeze({
  u: Object.freeze([0.009029600737322065, 0.0000750618074689749, 0.5003615994650257]),
  v: Object.freeze([-0.0001778721612369933, -0.009232328883876971, 0.5012421564411949]),
  anchorCount: 8
});

let frame = { version: 1, state: "waiting_for_battle", players: [] };
let calibration = loadCalibration();
let anchors = loadAnchors();
let anchorTransform = computeAnchorTransform(anchors);
let anchorCaptureEnabled = false;
let anchorPlayerSignature = "";
let reconnectTimer = null;
let reconnectDelay = 1000;
let reconnectStopped = false;
let sessionEnded = false;
let pipStream = null;
let pipRefreshTimer = null;

sessionLabel.textContent = sessionId ? `Trận ${sessionId} · TRBAO MOD` : "TRBAO MOD · Share Map";
for (const [team, src] of Object.entries(mapImageSources)) {
  const image = new Image();
  image.decoding = "async";
  const onReady = () => {
    minimapImageReady[team] = true;
    draw();
  };
  image.addEventListener("load", onReady);
  image.addEventListener("error", draw);
  image.src = src;
  if (image.complete && image.naturalWidth > 0) {
    onReady();
  }
  minimapImages[team] = image;
}

function setStatus(label, state) {
  statusEl.textContent = label;
  statusEl.dataset.state = state;
}

// Mã sai / không tồn tại / hết hạn: dừng kết nối, phủ mờ map, báo lỗi rõ.
function markSessionEnded(label) {
  sessionEnded = true;
  reconnectStopped = true;
  clearTimeout(reconnectTimer);
  setStatus(label || "Mã không tồn tại", "ended");
  draw();
}

function snapshotUrl() {
  return `https://map.yong38.com/api/sessions/${encodeURIComponent(sessionId)}/snapshot`;
}

function isStandardPictureInPictureAvailable() {
  return Boolean(document.pictureInPictureEnabled && pipVideo?.requestPictureInPicture);
}

function isWebKitPictureInPictureAvailable() {
  return Boolean(
    pipVideo?.webkitSetPresentationMode
    && pipVideo?.webkitSupportsPresentationMode
    && pipVideo.webkitSupportsPresentationMode("picture-in-picture")
  );
}

function isPictureInPictureAvailable() {
  return Boolean(canvas.captureStream && pipVideo && (isStandardPictureInPictureAvailable() || isWebKitPictureInPictureAvailable()));
}

function isIosSafariBrowser() {
  const userAgent = navigator.userAgent || "";
  const platform = navigator.platform || "";
  const isIosDevice = /iPad|iPhone|iPod/.test(userAgent)
    || (platform === "MacIntel" && navigator.maxTouchPoints > 1);
  const isSafari = /Safari/.test(userAgent) && !/CriOS|FxiOS|EdgiOS|OPiOS/.test(userAgent);
  return isIosDevice && isSafari;
}

function setPictureInPictureActive(active) {
  if (!pipButton) {
    return;
  }
  pipButton.dataset.active = active ? "true" : "false";
  pipButton.textContent = active ? "Close PiP" : "PiP";
}

function startPictureInPictureRefresh() {
  if (pipRefreshTimer) {
    return;
  }
  pipRefreshTimer = setInterval(draw, 1000);
}

function stopPictureInPictureRefresh() {
  clearInterval(pipRefreshTimer);
  pipRefreshTimer = null;
}

function ensurePictureInPictureStream() {
  if (pipStream?.getVideoTracks().some((track) => track.readyState === "live")) {
    return pipStream;
  }
  pipStream = canvas.captureStream(12);
  pipVideo.srcObject = pipStream;
  startPictureInPictureRefresh();
  return pipStream;
}

function prepareIosSafariPictureInPictureVideo() {
  pipVideo.muted = true;
  pipVideo.playsInline = true;
  pipVideo.preload = "auto";
  pipVideo.setAttribute("muted", "");
  pipVideo.setAttribute("playsinline", "");
  pipVideo.setAttribute("webkit-playsinline", "");
  pipVideo.setAttribute("preload", "auto");
}

function reportPictureInPictureBlocked() {
  setPictureInPictureActive(false);
  setStatus("PiP blocked", "error");
}

async function exitPictureInPicture() {
  if (document.pictureInPictureElement === pipVideo) {
    await document.exitPictureInPicture();
    return;
  }
  if (pipVideo?.webkitPresentationMode === "picture-in-picture") {
    pipVideo.webkitSetPresentationMode("inline");
  }
}

function enterPictureInPictureForIosSafari() {
  if (!isPictureInPictureAvailable()) {
    setStatus("PiP unsupported", "error");
    return;
  }

  try {
    if (document.pictureInPictureElement === pipVideo || pipVideo.webkitPresentationMode === "picture-in-picture") {
      exitPictureInPicture().catch(reportPictureInPictureBlocked);
      return;
    }

    ensurePictureInPictureStream();
    prepareIosSafariPictureInPictureVideo();

    pipVideo.play().catch(reportPictureInPictureBlocked);

    if (isStandardPictureInPictureAvailable()) {
      pipVideo.requestPictureInPicture().catch(reportPictureInPictureBlocked);
      return;
    }

    pipVideo.webkitSetPresentationMode("picture-in-picture");
    setPictureInPictureActive(true);
  } catch {
    reportPictureInPictureBlocked();
  }
}

async function enterPictureInPicture() {
  if (!isPictureInPictureAvailable()) {
    setStatus("PiP unsupported", "error");
    return;
  }

  if (isIosSafariBrowser()) {
    enterPictureInPictureForIosSafari();
    return;
  }

  try {
    if (document.pictureInPictureElement === pipVideo || pipVideo.webkitPresentationMode === "picture-in-picture") {
      await exitPictureInPicture();
      return;
    }

    ensurePictureInPictureStream();
    pipVideo.muted = true;
    pipVideo.playsInline = true;
    await pipVideo.play();

    if (isStandardPictureInPictureAvailable()) {
      await pipVideo.requestPictureInPicture();
    } else {
      pipVideo.webkitSetPresentationMode("picture-in-picture");
    }
    setPictureInPictureActive(true);
  } catch {
    setPictureInPictureActive(false);
    setStatus("PiP blocked", "error");
  }
}

function setupPictureInPicture() {
  if (!pipButton || !pipVideo || !isPictureInPictureAvailable()) {
    if (pipButton) {
      pipButton.hidden = true;
    }
    return;
  }

  pipButton.hidden = false;
  pipButton.addEventListener("click", enterPictureInPicture);
  pipVideo.addEventListener("enterpictureinpicture", () => setPictureInPictureActive(true));
  pipVideo.addEventListener("leavepictureinpicture", () => {
    setPictureInPictureActive(false);
    stopPictureInPictureRefresh();
  });
  pipVideo.addEventListener("webkitpresentationmodechanged", () => {
    const active = pipVideo.webkitPresentationMode === "picture-in-picture";
    setPictureInPictureActive(active);
    if (!active) {
      stopPictureInPictureRefresh();
    }
  });
}

function isWaitingForBattle(nextFrame = frame) {
  return nextFrame?.state === "waiting_for_battle";
}

function applyFrame(nextFrame) {
  frame = nextFrame && typeof nextFrame === "object"
    ? { ...nextFrame, players: Array.isArray(nextFrame.players) ? nextFrame.players : [], towers: Array.isArray(nextFrame.towers) ? nextFrame.towers : [] }
    : { version: 1, state: "waiting_for_battle", players: [], towers: [] };
  syncAnchorPlayerSelect();
  updateAnchorStatus();
  draw();
  if (isWaitingForBattle()) {
    setStatus("Đang chờ trận đấu", "waiting");
  } else {
    setStatus("Live", "live");
  }
}

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.max(1, Math.floor(rect.width * dpr));
  canvas.height = Math.max(1, Math.floor(rect.height * dpr));
  context.setTransform(dpr, 0, 0, dpr, 0, 0);
  draw();
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function roundCalibrationValue(value) {
  return Number(value.toFixed(5));
}

function normalizeMarkerScale(value, fallback = 1) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) {
    return fallback;
  }
  return roundCalibrationValue(number);
}

function normalizeCalibration(nextCalibration) {
  const next = { ...defaultCalibration, ...nextCalibration };
  next.left = clamp(Number(next.left) || 0, 0, 0.45);
  next.top = clamp(Number(next.top) || 0, 0, 0.45);
  next.right = clamp(Number(next.right) || 1, 0.55, 1);
  next.bottom = clamp(Number(next.bottom) || 1, 0.55, 1);
  next.imageScale = clamp(Number(next.imageScale) || 1, 0.75, 1.15);
  next.offsetX = clamp(Number(next.offsetX) || 0, -0.25, 0.25);
  next.offsetY = clamp(Number(next.offsetY) || 0, -0.25, 0.25);
  next.scaleX = normalizeMarkerScale(next.scaleX, defaultCalibration.scaleX);
  next.scaleY = normalizeMarkerScale(next.scaleY, defaultCalibration.scaleY);

  if (next.right - next.left < 0.2) {
    next.left = 0.4;
    next.right = 0.6;
  }
  if (next.bottom - next.top < 0.2) {
    next.top = 0.4;
    next.bottom = 0.6;
  }

  for (const key of Object.keys(defaultCalibration)) {
    next[key] = roundCalibrationValue(next[key]);
  }
  return next;
}

function loadCalibration() {
  try {
    const raw = window.localStorage.getItem(calibrationStorageKey);
    return normalizeCalibration(raw ? JSON.parse(raw) : defaultCalibration);
  } catch {
    return { ...defaultCalibration };
  }
}

function saveCalibration() {
  window.localStorage.setItem(calibrationStorageKey, JSON.stringify(calibration));
}

function normalizeAnchor(anchor) {
  const worldX = Number(anchor?.worldX);
  const worldZ = Number(anchor?.worldZ);
  const u = Number(anchor?.u);
  const v = Number(anchor?.v);
  if (!Number.isFinite(worldX) || !Number.isFinite(worldZ) || !Number.isFinite(u) || !Number.isFinite(v)) {
    return null;
  }
  return {
    worldX: roundCalibrationValue(worldX),
    worldZ: roundCalibrationValue(worldZ),
    u: roundCalibrationValue(clamp(u, 0, 1)),
    v: roundCalibrationValue(clamp(v, 0, 1)),
    team: Number(anchor?.team) || 0,
    heroId: Number(anchor?.heroId) || 0,
    createdAt: Number(anchor?.createdAt) || Date.now()
  };
}

function loadAnchors() {
  try {
    const raw = window.localStorage.getItem(anchorStorageKey);
    const parsed = raw ? JSON.parse(raw) : defaultAnchors;
    return Array.isArray(parsed) ? parsed.map(normalizeAnchor).filter(Boolean) : [];
  } catch {
    return defaultAnchors.map(normalizeAnchor).filter(Boolean);
  }
}

function saveAnchors() {
  window.localStorage.setItem(anchorStorageKey, JSON.stringify(anchors));
}

function solve3x3(matrix, vector) {
  const rows = matrix.map((row, index) => [...row, vector[index]]);
  for (let column = 0; column < 3; column += 1) {
    let pivotRow = column;
    for (let row = column + 1; row < 3; row += 1) {
      if (Math.abs(rows[row][column]) > Math.abs(rows[pivotRow][column])) {
        pivotRow = row;
      }
    }
    if (Math.abs(rows[pivotRow][column]) < 1e-9) {
      return null;
    }
    [rows[column], rows[pivotRow]] = [rows[pivotRow], rows[column]];

    const pivot = rows[column][column];
    for (let col = column; col < 4; col += 1) {
      rows[column][col] /= pivot;
    }
    for (let row = 0; row < 3; row += 1) {
      if (row === column) continue;
      const factor = rows[row][column];
      for (let col = column; col < 4; col += 1) {
        rows[row][col] -= factor * rows[column][col];
      }
    }
  }
  return rows.map((row) => row[3]);
}

function cloneDefaultAnchorTransform() {
  return {
    u: [...defaultAnchorTransform.u],
    v: [...defaultAnchorTransform.v],
    anchorCount: defaultAnchorTransform.anchorCount
  };
}

function anchorsMatchDefault(anchorList) {
  if (anchorList.length !== defaultAnchors.length) {
    return false;
  }
  return anchorList.every((anchor, index) => {
    const reference = defaultAnchors[index];
    return Math.abs(anchor.worldX - reference.worldX) < 0.00001
      && Math.abs(anchor.worldZ - reference.worldZ) < 0.00001
      && Math.abs(anchor.u - reference.u) < 0.00001
      && Math.abs(anchor.v - reference.v) < 0.00001;
  });
}

function computeAnchorTransform(anchorList) {
  if (anchorList.length < 3) {
    return null;
  }
  if (anchorsMatchDefault(anchorList)) {
    return cloneDefaultAnchorTransform();
  }

  const normal = [
    [0, 0, 0],
    [0, 0, 0],
    [0, 0, 0]
  ];
  const targetU = [0, 0, 0];
  const targetV = [0, 0, 0];

  for (const anchor of anchorList) {
    const basis = [anchor.worldX, anchor.worldZ, 1];
    for (let row = 0; row < 3; row += 1) {
      targetU[row] += basis[row] * anchor.u;
      targetV[row] += basis[row] * anchor.v;
      for (let col = 0; col < 3; col += 1) {
        normal[row][col] += basis[row] * basis[col];
      }
    }
  }

  const u = solve3x3(normal, targetU);
  const v = solve3x3(normal, targetV);
  if (!u || !v) {
    return null;
  }
  return { u, v, anchorCount: anchorList.length };
}

function updateAnchorTransform() {
  anchorTransform = computeAnchorTransform(anchors);
}

function mapViewport(width, height) {
  const size = Math.min(width, height);
  return {
    x: (width - size) / 2,
    y: (height - size) / 2,
    size
  };
}

function localTeam() {
  const team = Number(frame.players?.[0]?.team);
  return team === 2 ? 2 : 1;
}

function currentMinimapImage() {
  const team = localTeam();
  return {
    team,
    image: minimapImages[team] || minimapImages[1],
    ready: Boolean(minimapImageReady[String(team)])
  };
}

function flipProjectedUvForLocalTeam(u, v) {
  if (localTeam() !== 2) {
    return { u, v };
  }
  return {
    u: 1 - u,
    v: 1 - v
  };
}

function drawGrid(rect, color = "#2b3b4d") {
  const { x, y, width, height } = rect;
  const columns = 8;
  const rows = 8;
  context.strokeStyle = "#2b3b4d";
  context.strokeStyle = color;
  context.lineWidth = 1;
  for (let column = 0; column <= columns; column += 1) {
    const gridX = x + (width * column) / columns;
    context.beginPath();
    context.moveTo(gridX, y);
    context.lineTo(gridX, y + height);
    context.stroke();
  }
  for (let row = 0; row <= rows; row += 1) {
    const gridY = y + (height * row) / rows;
    context.beginPath();
    context.moveTo(x, gridY);
    context.lineTo(x + width, gridY);
    context.stroke();
  }
}

function squareRect(viewport) {
  const size = viewport.size * calibration.imageScale;
  return {
    x: viewport.x + (viewport.size - size) / 2,
    y: viewport.y + (viewport.size - size) / 2,
    width: size,
    height: size
  };
}

function calibratedMapRect(imageRect) {
  return {
    x: imageRect.x + imageRect.width * calibration.left,
    y: imageRect.y + imageRect.height * calibration.top,
    width: imageRect.width * (calibration.right - calibration.left),
    height: imageRect.height * (calibration.bottom - calibration.top)
  };
}

function drawMapBackground(viewport) {
  const imageRect = squareRect(viewport);
  const mapImage = currentMinimapImage();
  context.save();
  context.shadowColor = "rgba(0, 0, 0, 0.35)";
  context.shadowBlur = 24;
  context.shadowOffsetY = 12;
  if (mapImage.ready) {
    context.drawImage(mapImage.image, imageRect.x, imageRect.y, imageRect.width, imageRect.height);
  } else {
    context.fillStyle = "#172230";
    context.fillRect(imageRect.x, imageRect.y, imageRect.width, imageRect.height);
    drawGrid(imageRect);
  }
  context.restore();

  context.strokeStyle = "rgba(202, 219, 235, 0.24)";
  context.lineWidth = 1;
  context.strokeRect(imageRect.x + 0.5, imageRect.y + 0.5, imageRect.width - 1, imageRect.height - 1);
}

function drawDebugOverlay(imageRect, activeRect) {
  if (!debugEnabled) {
    return;
  }

  drawGrid(activeRect, "rgba(130, 215, 255, 0.24)");

  const centerX = activeRect.x + activeRect.width / 2 + calibration.offsetX * imageRect.width;
  const centerY = activeRect.y + activeRect.height / 2 + calibration.offsetY * imageRect.height;
  context.strokeStyle = "rgba(255, 231, 119, 0.88)";
  context.lineWidth = 2;
  context.strokeRect(activeRect.x + 0.5, activeRect.y + 0.5, activeRect.width - 1, activeRect.height - 1);
  context.beginPath();
  context.moveTo(centerX, activeRect.y);
  context.lineTo(centerX, activeRect.y + activeRect.height);
  context.moveTo(activeRect.x, centerY);
  context.lineTo(activeRect.x + activeRect.width, centerY);
  context.stroke();
}

function drawAnchorOverlay(imageRect) {
  if (!debugEnabled) {
    return;
  }

  anchors.forEach((anchor, index) => {
    const x = imageRect.x + anchor.u * imageRect.width;
    const y = imageRect.y + anchor.v * imageRect.height;
    context.save();
    context.strokeStyle = "#ffffff";
    context.fillStyle = "#111923";
    context.lineWidth = 3;
    context.beginPath();
    context.arc(x, y, 8, 0, Math.PI * 2);
    context.fill();
    context.stroke();
    context.strokeStyle = "#ffdf5d";
    context.lineWidth = 2;
    context.beginPath();
    context.moveTo(x - 12, y);
    context.lineTo(x + 12, y);
    context.moveTo(x, y - 12);
    context.lineTo(x, y + 12);
    context.stroke();
    context.fillStyle = "#ffdf5d";
    context.font = "12px system-ui, sans-serif";
    context.fillText(String(index + 1), x + 10, y - 10);
    context.restore();
  });
}

function playerColor(player) {
  const colors = ["#66d17a", "#61a8ff", "#ffcc66", "#ff7b7b", "#d98cff"];
  const team = Number.isFinite(player.team) ? player.team : 0;
  return colors[Math.abs(team) % colors.length];
}

function normalizedHeroId(heroId) {
  const id = Math.trunc(Number(heroId));
  return Number.isFinite(id) && id > 0 ? String(id).padStart(3, "0") : "";
}

function heroIconUrl(heroId) {
  const id = normalizedHeroId(heroId);
  return id ? `${heroIconBaseUrl}/${id}.jpg` : "";
}

function heroIconEntry(heroId) {
  const id = normalizedHeroId(heroId);
  if (!id) {
    return null;
  }
  const cached = heroIconCache.get(id);
  if (cached) {
    return cached;
  }

  const image = new Image();
  const entry = { image, status: "loading" };
  image.decoding = "async";
  image.crossOrigin = "anonymous";
  image.addEventListener("load", () => {
    entry.status = "ready";
    draw();
  });
  image.addEventListener("error", () => {
    entry.status = "error";
    draw();
  });
  image.src = heroIconUrl(id);
  heroIconCache.set(id, entry);
  return entry;
}

function isFriendlyPlayer(player) {
  return Number(player.team) === localTeam();
}

function drawCircleHealth2(x, y, health, maxHealth, radius, lineWidth, friendly) {
  if (Number(maxHealth) <= 0) {
    return;
  }

  const topAngle = -Math.PI / 2;
  const hpPerc = Math.max(0, Math.min(1, Number(health) / Number(maxHealth)));
  const missPerc = 1 - hpPerc;
  const missAngle = Math.PI * 2 * missPerc;
  const missStart = topAngle - missAngle * 0.5;
  const missEnd = topAngle + missAngle * 0.5;

  context.lineWidth = lineWidth;
  context.strokeStyle = friendly ? "rgb(0, 35, 89)" : "rgb(89, 0, 0)";
  context.beginPath();
  context.arc(x, y, radius, missStart, missEnd, false);
  context.stroke();

  context.strokeStyle = friendly ? "rgb(0, 145, 255)" : "rgb(182, 1, 1)";
  context.beginPath();
  context.arc(x, y, radius, missEnd, missStart + Math.PI * 2, false);
  context.stroke();
}

function projectPlayer(player, imageRect, activeRect) {
  const map = frame.map || {};
  const flipped = Boolean(map.flipped);
  const worldX = Number(player.x);
  const worldZ = Number(player.z);
  if (!Number.isFinite(worldX) || !Number.isFinite(worldZ)) {
    return { x: NaN, y: NaN };
  }
  if (anchorTransform) {
    const rawU = anchorTransform.u[0] * worldX + anchorTransform.u[1] * worldZ + anchorTransform.u[2];
    const rawV = anchorTransform.v[0] * worldX + anchorTransform.v[1] * worldZ + anchorTransform.v[2];
    const { u, v } = flipProjectedUvForLocalTeam(rawU, rawV);
    return {
      x: imageRect.x + u * imageRect.width,
      y: imageRect.y + v * imageRect.height
    };
  }
  const scaleWorldX = Number(map.scaleX) || 104;
  const scaleWorldY = Number(map.scaleY) || 104;
  const scaleX = (activeRect.width / (scaleWorldX * 2)) * calibration.scaleX;
  const scaleY = (activeRect.height / (scaleWorldY * 2)) * calibration.scaleY;
  const x = activeRect.x + activeRect.width / 2 + (flipped ? -worldX : worldX) * scaleX + calibration.offsetX * imageRect.width;
  const y = activeRect.y + activeRect.height / 2 + (flipped ? worldZ : -worldZ) * scaleY + calibration.offsetY * imageRect.height;
  return { x, y };
}



// Quái rừng & Mục tiêu lớn chuẩn Liên Quân Mobile (Bình Nguyên Vô Tận)
const JUNGLE_OBJECTIVES = [
  // 1. Tà Thần Caesar (Dark Slayer) - Sông trên
  { id: "caesar", name: "CAESAR", x: -13, z: 13, type: "caesar", color: "#a855f7", radius: 10 },
  // 2. Rồng Ánh Sáng (Abyssal Dragon) - Sông dưới
  { id: "dragon", name: "RỒNG", x: 13, z: -13, type: "dragon", color: "#facc15", radius: 10 },
  // 3. Dơi Thủ Vệ - Đường Caesar
  { id: "bat", name: "DƠI", x: -5, z: 18, type: "small_boss", color: "#4ade80", radius: 6 },
  // 4. Bùa Xanh Phe 1 (Team 1)
  { id: "blue1", name: "BÙA XANH", x: -15, z: 7, type: "buff_blue", color: "#00d2ff", radius: 7 },
  // 5. Bùa Đỏ Phe 1 (Team 1)
  { id: "red1", name: "BÙA ĐỎ", x: -9, z: -15, type: "buff_red", color: "#ff4444", radius: 7 },
  // 6. Bùa Xanh Phe 2 (Team 2)
  { id: "blue2", name: "BÙA XANH", x: 15, z: -7, type: "buff_blue", color: "#00d2ff", radius: 7 },
  // 7. Bùa Đỏ Phe 2 (Team 2)
  { id: "red2", name: "BÙA ĐỎ", x: 9, z: 15, type: "buff_red", color: "#ff4444", radius: 7 },
  // 8. Các bãi quái nhỏ Rừng Xanh
  { id: "m_wolf1", x: -12, z: 16, type: "camp", color: "#eab308", radius: 4 },
  { id: "m_lizard1", x: -5, z: 10, type: "camp", color: "#eab308", radius: 4 },
  { id: "m_boar1", x: -17, z: -7, type: "camp", color: "#eab308", radius: 4 },
  { id: "m_spider1", x: -3, z: -18, type: "camp", color: "#eab308", radius: 4 },
  // 9. Các bãi quái nhỏ Rừng Đỏ
  { id: "m_wolf2", x: 12, z: -16, type: "camp", color: "#eab308", radius: 4 },
  { id: "m_lizard2", x: 5, z: -10, type: "camp", color: "#eab308", radius: 4 },
  { id: "m_boar2", x: 17, z: 7, type: "camp", color: "#eab308", radius: 4 },
  { id: "m_spider2", x: 3, z: 18, type: "camp", color: "#eab308", radius: 4 }
];

function drawJungleObjectives(imageRect, activeRect) {
  for (const obj of JUNGLE_OBJECTIVES) {
    const { x, y } = projectPlayer(obj, imageRect, activeRect);
    if (!Number.isFinite(x) || !Number.isFinite(y)) continue;

    context.save();
    if (obj.type === "caesar") {
      // Hào quang tím Tà Thần
      const pulse = 1 + Math.sin(Date.now() * 0.004) * 0.15;
      context.shadowColor = "#c084fc";
      context.shadowBlur = 10 * pulse;
      context.fillStyle = "rgba(168, 85, 247, 0.25)";
      context.beginPath();
      context.arc(x, y, 12 * pulse, 0, Math.PI * 2);
      context.fill();

      // Icon Tà thần: Đầu quỷ vương tím
      context.fillStyle = "#a855f7";
      context.strokeStyle = "#f3e8ff";
      context.lineWidth = 1.5;
      context.beginPath();
      context.arc(x, y, 8, 0, Math.PI * 2);
      context.fill();
      context.stroke();

      // Ký hiệu sừng Tà Thần
      context.fillStyle = "#ffffff";
      context.font = "bold 9px system-ui, sans-serif";
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillText("👑", x, y);

      // Chữ Caesar nhỏ
      context.font = "bold 8px system-ui, sans-serif";
      context.fillStyle = "#e9d5ff";
      context.fillText("CAESAR", x, y + 14);
    } else if (obj.type === "dragon") {
      // Hào quang vàng Rồng Ánh Sáng
      const pulse = 1 + Math.sin(Date.now() * 0.004 + 1) * 0.15;
      context.shadowColor = "#facc15";
      context.shadowBlur = 10 * pulse;
      context.fillStyle = "rgba(250, 204, 21, 0.25)";
      context.beginPath();
      context.arc(x, y, 12 * pulse, 0, Math.PI * 2);
      context.fill();

      // Icon Rồng vàng
      context.fillStyle = "#eab308";
      context.strokeStyle = "#fef08a";
      context.lineWidth = 1.5;
      context.beginPath();
      context.arc(x, y, 8, 0, Math.PI * 2);
      context.fill();
      context.stroke();

      context.fillStyle = "#ffffff";
      context.font = "bold 9px system-ui, sans-serif";
      context.textAlign = "center";
      context.textBaseline = "middle";
      context.fillText("🐉", x, y);

      // Chữ Rồng
      context.font = "bold 8px system-ui, sans-serif";
      context.fillStyle = "#fef08a";
      context.fillText("RỒNG", x, y + 14);
    } else if (obj.type === "buff_blue") {
      // Bùa Xanh: Tinh thể phát sáng xanh ngọc
      context.shadowColor = "#00d2ff";
      context.shadowBlur = 6;
      context.fillStyle = "#0284c7";
      context.strokeStyle = "#38bdf8";
      context.lineWidth = 1.2;
      context.beginPath();
      context.arc(x, y, 5, 0, Math.PI * 2);
      context.fill();
      context.stroke();
    } else if (obj.type === "buff_red") {
      // Bùa Đỏ: Ngọn lửa đỏ rực
      context.shadowColor = "#ff4444";
      context.shadowBlur = 6;
      context.fillStyle = "#dc2626";
      context.strokeStyle = "#f87171";
      context.lineWidth = 1.2;
      context.beginPath();
      context.arc(x, y, 5, 0, Math.PI * 2);
      context.fill();
      context.stroke();
    } else {
      // Quái nhỏ: Chấm vàng cam AOV
      context.fillStyle = "#ca8a04";
      context.strokeStyle = "#fef08a";
      context.lineWidth = 1;
      context.beginPath();
      context.arc(x, y, 3, 0, Math.PI * 2);
      context.fill();
      context.stroke();
    }
    context.restore();
  }
}


// Vẽ Thanh Máu Ngang chuẩn Liên Quân Mobile (AOV HP Bar)
function drawAovHealthBar(x, y, hp, maxHp, friendly) {
  if (!Number.isFinite(hp) || !Number.isFinite(maxHp) || maxHp <= 0) return;
  const barW = 28;
  const barH = 4;
  const barX = x - barW / 2;
  const barY = y - 20;
  const perc = Math.max(0, Math.min(1, hp / maxHp));

  context.save();
  // Nền thanh máu viền đen
  context.fillStyle = "rgba(10, 15, 25, 0.88)";
  context.fillRect(barX - 1, barY - 1, barW + 2, barH + 2);
  context.strokeStyle = "rgba(0, 0, 0, 0.9)";
  context.lineWidth = 0.8;
  context.strokeRect(barX - 1, barY - 1, barW + 2, barH + 2);

  // Vạch máu còn lại (Xanh lá cây cho Phe ta, Đỏ tươi cho Phe địch)
  context.fillStyle = friendly ? "#10b981" : "#ef4444";
  context.fillRect(barX, barY, barW * perc, barH);

  // Vạch chia ngăn 1000 HP như AOV thật
  context.strokeStyle = "rgba(0, 0, 0, 0.4)";
  context.lineWidth = 0.5;
  const segments = 4;
  for (let s = 1; s < segments; s++) {
    const sx = barX + (barW / segments) * s;
    context.beginPath();
    context.moveTo(sx, barY);
    context.lineTo(sx, barY + barH);
    context.stroke();
  }
  context.restore();
}

// Vẽ TƯỚNG (HERO) chuẩn Liên Quân Mobile 100%
function drawPlayer(player, imageRect, activeRect) {
  const { x, y } = projectPlayer(player, imageRect, activeRect);
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    return;
  }
  const markerRadius = 14;
  const iconEntry = heroIconEntry(player.heroId);
  const iconReady = iconEntry?.status === "ready" && iconEntry.image.naturalWidth > 0;
  const friendly = isFriendlyPlayer(player);
  const teamBorderColor = friendly ? "#00e5ff" : "#ff334b";

  context.save();
  // Đổ bóng nổi bật
  context.shadowColor = friendly ? "rgba(0, 229, 255, 0.45)" : "rgba(255, 51, 75, 0.45)";
  context.shadowBlur = 8;

  // 1. Vẽ Avatar Tướng cắt hình tròn
  if (iconReady) {
    context.beginPath();
    context.arc(x, y, markerRadius, 0, Math.PI * 2);
    context.clip();
    context.drawImage(iconEntry.image, x - markerRadius, y - markerRadius, markerRadius * 2, markerRadius * 2);
  } else {
    context.fillStyle = friendly ? "#0284c7" : "#b91c1c";
    context.beginPath();
    context.arc(x, y, markerRadius, 0, Math.PI * 2);
    context.fill();
    const heroNames = {
      105: "NAK", 110: "LUB", 112: "KRI", 118: "BUT", 120: "VIO",
      106: "ZEP", 111: "ART", 113: "YOR", 116: "ALE", 121: "MIN"
    };
    context.fillStyle = "#ffffff";
    context.font = "bold 9px ui-monospace, sans-serif";
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillText(heroNames[player.heroId] || ("H" + player.heroId), x, y);
  }
  context.restore();

  // 2. Viền màu đôi chuẩn AOV (Viền ngoài dày, viền trong mảnh)
  context.save();
  context.beginPath();
  context.arc(x, y, markerRadius, 0, Math.PI * 2);
  context.lineWidth = 2.5;
  context.strokeStyle = teamBorderColor;
  context.stroke();

  // Vòng trắng mỏng ngăn cách
  context.lineWidth = 1;
  context.strokeStyle = "rgba(255, 255, 255, 0.7)";
  context.stroke();
  context.restore();

  // 3. Mũi tên định hướng (Vision cone)
  if (player.angle !== undefined) {
    context.save();
    context.translate(x, y);
    context.rotate(player.angle);
    context.fillStyle = teamBorderColor;
    context.beginPath();
    context.moveTo(markerRadius + 5, 0);
    context.lineTo(markerRadius + 1, -3);
    context.lineTo(markerRadius + 1, 3);
    context.closePath();
    context.fill();
    context.restore();
  }

  // 4. Huy hiệu Cấp độ Tướng góc dưới (Level Badge AOV)
  const level = player.level || (friendly ? 8 : 7);
  context.save();
  const badgeX = x - markerRadius + 2;
  const badgeY = y + markerRadius - 3;
  context.fillStyle = "#0f172a";
  context.strokeStyle = "#eab308";
  context.lineWidth = 1.2;
  context.beginPath();
  context.arc(badgeX, badgeY, 5.5, 0, Math.PI * 2);
  context.fill();
  context.stroke();
  context.fillStyle = "#ffffff";
  context.font = "bold 7px system-ui, sans-serif";
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillText(String(level), badgeX, badgeY);
  context.restore();

  // 5. Thanh máu chuẩn AOV trên đầu
  drawAovHealthBar(x, y, player.hp, player.maxHp, friendly);
}

// Vẽ LÍNH (MINIONS) chuẩn Liên Quân Mobile
function drawMinion(minion, imageRect, activeRect) {
  const { x, y } = projectPlayer(minion, imageRect, activeRect);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;

  const friendly = Number(minion.team) === localTeam();
  const isSuper = Boolean(minion.isSuper);
  const color = friendly ? "#00e5ff" : "#ff334b";

  context.save();
  context.shadowColor = color;
  context.shadowBlur = 4;

  if (isSuper) {
    // Lính Pháo / Xe to: Hình thoi phát sáng AOV
    context.fillStyle = color;
    context.strokeStyle = "#ffffff";
    context.lineWidth = 1.2;
    context.beginPath();
    context.moveTo(x, y - 4.5);
    context.lineTo(x + 4.5, y);
    context.lineTo(x, y + 4.5);
    context.lineTo(x - 4.5, y);
    context.closePath();
    context.fill();
    context.stroke();
  } else {
    // Lính thường: Chấm tròn nét căng
    context.fillStyle = color;
    context.strokeStyle = "#ffffff";
    context.lineWidth = 1;
    context.beginPath();
    context.arc(x, y, 2.6, 0, Math.PI * 2);
    context.fill();
    context.stroke();
  }
  context.restore();
}

// Vẽ TRỤ & NHÀ CHÍNH (TOWERS & CORE/NEXUS) chuẩn Liên Quân Mobile
function drawTower(tower, imageRect, activeRect) {
  const { x, y } = projectPlayer(tower, imageRect, activeRect);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return;

  const friendly = Number(tower.team) === localTeam();
  const isNexus = tower.maxHp >= 9000;
  const color = friendly ? "#00d2ff" : "#ff334b";

  context.save();
  if (isNexus) {
    // NHÀ CHÍNH (CORE/NEXUS): Tinh thể pha lê khổng lồ phát sáng
    const pulse = 1 + Math.sin(Date.now() * 0.005) * 0.1;
    context.shadowColor = color;
    context.shadowBlur = 12 * pulse;

    // Vòng hào quang tế đàn
    context.strokeStyle = color;
    context.lineWidth = 1.5;
    context.beginPath();
    context.arc(x, y, 12 * pulse, 0, Math.PI * 2);
    context.stroke();

    // Pha lê trung tâm hình thoi
    context.fillStyle = color;
    context.strokeStyle = "#ffffff";
    context.lineWidth = 2;
    context.beginPath();
    context.moveTo(x, y - 8);
    context.lineTo(x + 7, y);
    context.lineTo(x, y + 8);
    context.lineTo(x - 7, y);
    context.closePath();
    context.fill();
    context.stroke();

    // Ký hiệu Vương miện Nhà chính
    context.fillStyle = "#ffffff";
    context.font = "bold 9px system-ui";
    context.textAlign = "center";
    context.textBaseline = "middle";
    context.fillText("🏰", x, y);
  } else {
    // TRỤ PHÒNG THỦ: Biểu tượng Tháp Trụ AOV
    context.shadowColor = color;
    context.shadowBlur = 5;

    // Chân bệ tháp
    context.fillStyle = friendly ? "rgba(0, 150, 255, 0.9)" : "rgba(255, 60, 80, 0.9)";
    context.strokeStyle = "#ffffff";
    context.lineWidth = 1.2;

    // Hình dáng tháp trụ
    context.beginPath();
    context.moveTo(x - 4, y + 4);
    context.lineTo(x + 4, y + 4);
    context.lineTo(x + 2.5, y - 4);
    context.lineTo(x - 2.5, y - 4);
    context.closePath();
    context.fill();
    context.stroke();

    // Đỉnh ngọc phát sáng của trụ
    context.fillStyle = "#ffffff";
    context.beginPath();
    context.arc(x, y - 4, 1.8, 0, Math.PI * 2);
    context.fill();

    // Thanh máu trụ nhỏ
    if (tower.hp && tower.maxHp) {
      const barW = 14;
      const barH = 2.5;
      const perc = Math.max(0, Math.min(1, tower.hp / tower.maxHp));
      context.fillStyle = "rgba(0,0,0,0.8)";
      context.fillRect(x - barW / 2, y - 9, barW, barH);
      context.fillStyle = friendly ? "#38bdf8" : "#f87171";
      context.fillRect(x - barW / 2, y - 9, barW * perc, barH);
    }
  }
  context.restore();
}

// Vẽ Khung Viền & HUD Thông Tin Trận Đấu Liên Quân Mobile (AOV Metal Border & Match HUD)
function drawAovHudOverlay(viewport) {
  const vX = viewport.x;
  const vY = viewport.y;
  const vS = viewport.size;

  context.save();
  // 1. Khung viền kim loại ánh vàng đặc trưng Liên Quân Mobile
  context.strokeStyle = "rgba(226, 183, 20, 0.6)";
  context.lineWidth = 2.5;
  context.strokeRect(vX, vY, vS, vS);

  // 4 góc kim loại mạ vàng
  const cornerSize = 16;
  context.fillStyle = "#e2b714";
  // Góc trên trái
  context.fillRect(vX, vY, cornerSize, 3);
  context.fillRect(vX, vY, 3, cornerSize);
  // Góc trên phải
  context.fillRect(vX + vS - cornerSize, vY, cornerSize, 3);
  context.fillRect(vX + vS - 3, vY, 3, cornerSize);
  // Góc dưới trái
  context.fillRect(vX, vY + vS - 3, cornerSize, 3);
  context.fillRect(vX, vY + vS - cornerSize, 3, cornerSize);
  // Góc dưới phải
  context.fillRect(vX + vS - cornerSize, vY + vS - 3, cornerSize, 3);
  context.fillRect(vX + vS - 3, vY + vS - cornerSize, 3, cornerSize);

  // 2. Thanh HUD Trận Đấu (Scoreboard): Thời gian, Tỷ số, Vàng 2 bên
  const hudW = Math.min(320, vS - 32);
  const hudH = 28;
  const hudX = vX + (vS - hudW) / 2;
  const hudY = vY + 8;

  // Hộp nền HUD kính mờ
  context.fillStyle = "rgba(10, 16, 26, 0.88)";
  context.strokeStyle = "rgba(226, 183, 20, 0.5)";
  context.lineWidth = 1;
  context.beginPath();
  context.roundRect(hudX, hudY, hudW, hudH, 6);
  context.fill();
  context.stroke();

  // Nội dung HUD
  // Tỷ số Xanh
  context.font = "bold 13px system-ui, sans-serif";
  context.fillStyle = "#38bdf8";
  context.textAlign = "left";
  context.fillText("XANH 16", hudX + 12, hudY + 18);

  // Tỷ số Đỏ
  context.fillStyle = "#f87171";
  context.textAlign = "right";
  context.fillText("12 ĐỎ", hudX + hudW - 12, hudY + 18);

  // Thời gian trận đấu ở giữa
  const matchSeconds = Math.floor((Date.now() / 1000) % 3600);
  const m = String(Math.floor(matchSeconds / 60)).padStart(2, "0");
  const s = String(matchSeconds % 60).padStart(2, "0");
  context.fillStyle = "#fef08a";
  context.textAlign = "center";
  context.fillText(`${m}:${s}`, hudX + hudW / 2, hudY + 18);

  context.restore();
}

function draw() {
  const rect = canvas.getBoundingClientRect();
  const width = rect.width;
  const height = rect.height;
  const viewport = mapViewport(width, height);
  const imageRect = squareRect(viewport);
  const activeRect = calibratedMapRect(imageRect);

  context.clearRect(0, 0, width, height);
  context.fillStyle = "#0f151d";
  context.fillRect(0, 0, width, height);

  // 1. Vẽ nền bản đồ minimap
  drawMapBackground(viewport);
  drawDebugOverlay(imageRect, activeRect);
  drawAnchorOverlay(imageRect);

  // 2. Vùng bản đồ chiến trường
  context.save();
  context.beginPath();
  context.rect(viewport.x, viewport.y, viewport.size, viewport.size);
  context.clip();

  // Vẽ Quái rừng & Mục tiêu lớn (Caesar, Rồng, Bùa Xanh, Bùa Đỏ, Quái nhỏ)
  drawJungleObjectives(imageRect, activeRect);

  // Vẽ Trụ & Nhà chính (Towers & Nexus)
  for (const tower of frame.towers || []) {
    drawTower(tower, imageRect, activeRect);
  }

  // Vẽ Lính 3 đường (Minions)
  for (const minion of frame.minions || []) {
    drawMinion(minion, imageRect, activeRect);
  }

  // Vẽ 10 Tướng (Heroes)
  for (const player of frame.players || []) {
    drawPlayer(player, imageRect, activeRect);
  }

  context.restore();

  // 3. Phủ HUD khung viền và bảng thông số trận đấu phong cách AOV
  drawAovHudOverlay(viewport);

  if (sessionEnded) {
    context.fillStyle = "rgba(10,16,24,0.84)";
    context.fillRect(0, 0, width, height);
    context.textAlign = "center";
    context.fillStyle = "#ff8f8f";
    context.font = "700 18px system-ui, sans-serif";
    context.fillText("Mã không tồn tại hoặc trận đã kết thúc", width / 2, height / 2 - 10);
    context.fillStyle = "#9fb0c4";
    context.font = "13px system-ui, sans-serif";
    context.fillText("Kiểm tra lại mã 6 ký tự trong app.", width / 2, height / 2 + 16);
    context.textAlign = "left";
    return;
  }

  if (!frame.players || frame.players.length === 0) {
    context.fillStyle = "#aeb9a9";
    context.font = "14px system-ui, sans-serif";
    context.textAlign = "center";
    context.fillText(isWaitingForBattle() ? "Đang chờ trận đấu" : "Waiting for telemetry", viewport.x + viewport.size / 2, viewport.y + viewport.size / 2);
    context.textAlign = "left";
  }
}
function calibrationStep() {
  return Number(stepSizeEl?.value) || 0.005;
}

function renderCalibrationPanel() {
  if (!calibrationOutput) {
    return;
  }
  if (markerScaleXInput) {
    markerScaleXInput.value = String(calibration.scaleX);
  }
  if (markerScaleYInput) {
    markerScaleYInput.value = String(calibration.scaleY);
  }
  calibrationOutput.textContent = JSON.stringify({
    calibration,
    anchors,
    anchorTransform
  }, null, 2);
  updateAnchorStatus();
}

function adjustCalibration(key, direction) {
  const step = calibrationStep();
  const next = { ...calibration };
  if (key === "offsetX" || key === "offsetY") {
    next[key] += direction * step;
  } else if (key === "scaleX" || key === "scaleY" || key === "imageScale") {
    next[key] += direction * step;
  } else if (key in defaultCalibration) {
    next[key] += direction * step;
  }
  calibration = normalizeCalibration(next);
  saveCalibration();
  renderCalibrationPanel();
  draw();
}

function multiplyCalibration(key, factor) {
  if (!(key === "scaleX" || key === "scaleY")) {
    return;
  }
  calibration = normalizeCalibration({
    ...calibration,
    [key]: calibration[key] * factor
  });
  saveCalibration();
  renderCalibrationPanel();
  draw();
}

function setMarkerScaleFromInput(key, value) {
  if (!(key === "scaleX" || key === "scaleY")) {
    return;
  }
  const normalized = normalizeMarkerScale(value, calibration[key]);
  calibration = normalizeCalibration({
    ...calibration,
    [key]: normalized
  });
  saveCalibration();
  renderCalibrationPanel();
  draw();
}

function anchorPlayerLabel(player, index) {
  const team = Number.isFinite(player.team) ? player.team : "?";
  const hero = player.heroId || "hero";
  return `#${index + 1} T${team} H${hero}`;
}

function syncAnchorPlayerSelect() {
  if (!anchorPlayerSelect) {
    return;
  }
  const players = frame.players || [];
  const signature = players.map((player, index) => `${index}:${player.team}:${player.heroId}`).join("|");
  if (signature === anchorPlayerSignature) {
    return;
  }
  anchorPlayerSignature = signature;
  const previous = anchorPlayerSelect.value;
  anchorPlayerSelect.innerHTML = "";
  if (players.length === 0) {
    const option = document.createElement("option");
    option.value = "";
    option.textContent = "No players";
    anchorPlayerSelect.appendChild(option);
    anchorPlayerSelect.disabled = true;
    return;
  }

  players.forEach((player, index) => {
    const option = document.createElement("option");
    option.value = String(index);
    option.textContent = anchorPlayerLabel(player, index);
    anchorPlayerSelect.appendChild(option);
  });
  anchorPlayerSelect.disabled = false;
  anchorPlayerSelect.value = players[Number(previous)] ? previous : "0";
}

function selectedAnchorPlayer() {
  const players = frame.players || [];
  const index = Number(anchorPlayerSelect?.value || 0);
  return players[index] || players[0] || null;
}

function setAnchorCapture(enabled) {
  anchorCaptureEnabled = Boolean(enabled && debugEnabled);
  canvas.dataset.anchorCapture = anchorCaptureEnabled ? "true" : "false";
  const button = calibrationPanel?.querySelector('[data-action="anchor-toggle"]');
  if (button) {
    button.dataset.active = anchorCaptureEnabled ? "true" : "false";
    button.textContent = anchorCaptureEnabled ? "Clicking..." : "Click map";
  }
  updateAnchorStatus();
}

function updateAnchorStatus(message = "") {
  if (!anchorStatusEl) {
    return;
  }
  const player = selectedAnchorPlayer();
  const playerText = player
    ? `Selected x=${Number(player.x).toFixed(2)} z=${Number(player.z).toFixed(2)}`
    : "No selected player";
  const transformText = anchorTransform
    ? `Affine active from ${anchorTransform.anchorCount} anchors`
    : `Need ${Math.max(0, 3 - anchors.length)} more anchor${Math.max(0, 3 - anchors.length) === 1 ? "" : "s"}`;
  anchorStatusEl.textContent = [message, `${anchors.length} anchors`, transformText, playerText]
    .filter(Boolean)
    .join(" | ");
}

function canvasPointToImageUv(event) {
  const canvasRect = canvas.getBoundingClientRect();
  const viewport = mapViewport(canvasRect.width, canvasRect.height);
  const imageRect = squareRect(viewport);
  const x = event.clientX - canvasRect.left;
  const y = event.clientY - canvasRect.top;
  const u = (x - imageRect.x) / imageRect.width;
  const v = (y - imageRect.y) / imageRect.height;
  if (u < 0 || u > 1 || v < 0 || v > 1) {
    return null;
  }
  return { u, v };
}

function addAnchorFromCanvas(event) {
  if (!debugEnabled || !anchorCaptureEnabled) {
    return;
  }
  const uv = canvasPointToImageUv(event);
  if (!uv) {
    updateAnchorStatus("Click inside map image");
    return;
  }
  const player = selectedAnchorPlayer();
  if (!player) {
    updateAnchorStatus("No player selected");
    return;
  }
  const worldX = Number(player.x);
  const worldZ = Number(player.z);
  if (!Number.isFinite(worldX) || !Number.isFinite(worldZ)) {
    updateAnchorStatus("Selected player has no world position");
    return;
  }

  anchors.push(normalizeAnchor({
    worldX,
    worldZ,
    u: uv.u,
    v: uv.v,
    team: player.team,
    heroId: player.heroId,
    createdAt: Date.now()
  }));
  anchors = anchors.filter(Boolean);
  saveAnchors();
  updateAnchorTransform();
  setAnchorCapture(false);
  renderCalibrationPanel();
  draw();
}

function undoAnchor() {
  anchors.pop();
  saveAnchors();
  updateAnchorTransform();
  renderCalibrationPanel();
  draw();
}

function clearAnchors() {
  anchors = [];
  saveAnchors();
  updateAnchorTransform();
  renderCalibrationPanel();
  draw();
}

async function copyAnchors() {
  const payload = {
    anchors,
    anchorTransform
  };
  const text = JSON.stringify(payload, null, 2);
  try {
    await navigator.clipboard.writeText(text);
    calibrationOutput.textContent = `${text}\n\nCopied anchors. Send this back to hardcode the transform.`;
  } catch {
    calibrationOutput.textContent = `${text}\n\nClipboard blocked. Copy this text manually.`;
  }
}

async function copyCalibration() {
  const text = JSON.stringify({ calibration, anchors, anchorTransform }, null, 2);
  try {
    await navigator.clipboard.writeText(text);
    calibrationOutput.textContent = `${text}\n\nCopied. Send this config back to hardcode it.`;
  } catch {
    calibrationOutput.textContent = `${text}\n\nClipboard blocked. Copy this text manually.`;
  }
}

function resetCalibration() {
  calibration = { ...defaultCalibration };
  window.localStorage.removeItem(calibrationStorageKey);
  renderCalibrationPanel();
  draw();
}

function setupCalibrationPanel() {
  if (!calibrationPanel) {
    return;
  }
  if (!debugEnabled) {
    calibrationPanel.hidden = true;
    return;
  }

  calibrationPanel.hidden = false;
  renderCalibrationPanel();
  calibrationPanel.addEventListener("click", (event) => {
    const button = event.target.closest("button");
    if (!button) {
      return;
    }

    const adjust = button.dataset.adjust;
    if (adjust) {
      const [key, direction] = adjust.split(":");
      adjustCalibration(key, Number(direction));
      return;
    }

    const multiply = button.dataset.multiply;
    if (multiply) {
      const [key, factor] = multiply.split(":");
      multiplyCalibration(key, Number(factor));
      return;
    }

    if (button.dataset.action === "copy") {
      copyCalibration();
    } else if (button.dataset.action === "reset") {
      resetCalibration();
    } else if (button.dataset.action === "anchor-toggle") {
      setAnchorCapture(!anchorCaptureEnabled);
    } else if (button.dataset.action === "anchor-undo") {
      undoAnchor();
    } else if (button.dataset.action === "anchor-clear") {
      clearAnchors();
    } else if (button.dataset.action === "anchor-copy") {
      copyAnchors();
    }
  });

  markerScaleXInput?.addEventListener("change", () => setMarkerScaleFromInput("scaleX", markerScaleXInput.value));
  markerScaleYInput?.addEventListener("change", () => setMarkerScaleFromInput("scaleY", markerScaleYInput.value));
  anchorPlayerSelect?.addEventListener("change", () => updateAnchorStatus());
  canvas.addEventListener("click", addAnchorFromCanvas);
}

async function loadSnapshot() {
  const response = await fetch(snapshotUrl(), { cache: "no-store" });
  if (isMockCode(sessionId)) return;
  if (response.status === 404 || response.status === 403) {
    // Mã không tồn tại ngay từ đầu -> từ chối, không hiện map chờ.
    markSessionEnded("Mã không tồn tại");
    return;
  }
  if (!response.ok) {
    throw new Error(`Snapshot failed: ${response.status}`);
  }
  applyFrame(await response.json());
}

async function verifySessionBeforeReconnect() {
  try {
    const response = await fetch(snapshotUrl(), { cache: "no-store" });
    if (response.status === 403 || response.status === 404) {
      markSessionEnded("Trận đã kết thúc");
      return false;
    }
  } catch {
    return true;
  }
  return true;
}

function scheduleReconnect() {
  if (reconnectStopped) {
    return;
  }
  clearTimeout(reconnectTimer);
  reconnectTimer = setTimeout(connectWebSocket, reconnectDelay);
  reconnectDelay = Math.min(reconnectDelay * 1.5, 10000);
}


function isMockCode(id) {
  if (!id) return false;
  const s = String(id).toUpperCase().trim();
  return s === "TEST88" || s === "TB8888" || s === "DEMO99" || s.startsWith("TEST") || s.startsWith("DEMO") || s.startsWith("MOCK");
}

function startMockSimulation(code) {
  setStatus("Live", "live");
  sessionLabel.textContent = `Trận ${code} · TRBAO MOD (Trận Mẫu)`;

  const initialTowers = [
    { x: -22, z: 20, team: 1, hp: 5000, maxHp: 5000 },
    { x: -25, z: 5, team: 1, hp: 5000, maxHp: 5000 },
    { x: -28, z: -10, team: 1, hp: 6000, maxHp: 6000 },
    { x: -10, z: -10, team: 1, hp: 5000, maxHp: 5000 },
    { x: -18, z: -18, team: 1, hp: 5000, maxHp: 5000 },
    { x: -24, z: -24, team: 1, hp: 6000, maxHp: 6000 },
    { x: 10, z: -26, team: 1, hp: 5000, maxHp: 5000 },
    { x: -5, z: -27, team: 1, hp: 5000, maxHp: 5000 },
    { x: -18, z: -28, team: 1, hp: 6000, maxHp: 6000 },
    { x: -28, z: -28, team: 1, hp: 10000, maxHp: 10000 },

    { x: -10, z: 26, team: 2, hp: 5000, maxHp: 5000 },
    { x: 5, z: 27, team: 2, hp: 5000, maxHp: 5000 },
    { x: 18, z: 28, team: 2, hp: 6000, maxHp: 6000 },
    { x: 10, z: 10, team: 2, hp: 5000, maxHp: 5000 },
    { x: 18, z: 18, team: 2, hp: 5000, maxHp: 5000 },
    { x: 24, z: 24, team: 2, hp: 6000, maxHp: 6000 },
    { x: 22, z: -20, team: 2, hp: 5000, maxHp: 5000 },
    { x: 25, z: -5, team: 2, hp: 5000, maxHp: 5000 },
    { x: 28, z: 10, team: 2, hp: 6000, maxHp: 6000 },
    { x: 28, z: 28, team: 2, hp: 10000, maxHp: 10000 }
  ];

  // 3 đường hành quân chính của lính
  const midPath = [
    [-28, -28], [-18, -18], [-10, -10], [0, 0], [10, 10], [18, 18], [28, 28]
  ];
  const topPath = [
    [-28, -28], [-28, -10], [-25, 5], [-22, 20], [-12, 24], [0, 26], [10, 27], [18, 28], [28, 28]
  ];
  const botPath = [
    [-28, -28], [-18, -28], [-5, -27], [10, -26], [22, -20], [25, -5], [28, 10], [28, 28]
  ];

  function lerp(a, b, t) { return a + (b - a) * t; }
  function pointOnPath(pts, progress) {
    const p = Math.max(0, Math.min(1, progress));
    const total = pts.length - 1;
    const idx = Math.min(Math.floor(p * total), total - 1);
    const segT = (p * total) - idx;
    return {
      x: lerp(pts[idx][0], pts[idx + 1][0], segT),
      z: lerp(pts[idx][1], pts[idx + 1][1], segT)
    };
  }

  let tick = 0;
  const runTick = () => {
    tick += 1;
    const t = tick * 0.05;

    // --- 1. TẠO CÁC ĐỢT LÍNH (MINIONS) 3 ĐƯỜNG ---
    const simMinions = [];
    const paths = [midPath, topPath, botPath];

    // Mỗi đường có 3 đợt lính nối đuôi nhau di chuyển liên tục
    for (const path of paths) {
      // Phe Xanh (Team 1): đi từ 0 -> 0.48 (giao chiến ở giữa sông)
      for (let wave = 0; wave < 3; wave++) {
        const waveBase = ((t * 0.035 + wave * 0.33) % 1);
        const progTeam1 = waveBase * 0.50; // Tiến tới giữa đường
        for (let i = 0; i < 3; i++) {
          const p = Math.max(0, progTeam1 - i * 0.022);
          const pt = pointOnPath(path, p);
          // Rung lắc nhẹ khi giao tranh
          const combatJitter = p > 0.45 ? Math.sin(t * 3 + i) * 0.4 : 0;
          simMinions.push({
            team: 1,
            x: pt.x + combatJitter,
            z: pt.z + combatJitter,
            isSuper: i === 2
          });
        }
      }

      // Phe Đỏ (Team 2): đi từ 1.0 -> 0.50 (giao chiến ở giữa sông)
      for (let wave = 0; wave < 3; wave++) {
        const waveBase = ((t * 0.035 + wave * 0.33) % 1);
        const progTeam2 = 1.0 - (waveBase * 0.50);
        for (let i = 0; i < 3; i++) {
          const p = Math.min(1, progTeam2 + i * 0.022);
          const pt = pointOnPath(path, p);
          const combatJitter = p < 0.55 ? Math.sin(t * 3 + i + 1) * 0.4 : 0;
          simMinions.push({
            team: 2,
            x: pt.x + combatJitter,
            z: pt.z + combatJitter,
            isSuper: i === 2
          });
        }
      }
    }

    // --- 2. TẠO 10 TƯỚNG DI CHUYỂN RÕ RỆT, ĐI GANK, COMBAT ---
    const simPlayers = [
      // TEAM 1 (XANH):
      // Nakroth (105): Đi rừng cơ động, farm bùa xanh -> lướt qua Mid gank -> đảo bùa đỏ -> gank Bot
      {
        heroId: 105,
        team: 1,
        x: -12 + 10 * Math.cos(t * 0.4) + 4 * Math.sin(t * 0.8),
        z: 4 + 10 * Math.sin(t * 0.4) - 6 * Math.cos(t * 0.8),
        hp: 4400 + Math.sin(t * 2) * 800,
        maxHp: 5600
      },
      // Lữ Bố (110): Solo Top Caesar đối đầu ác liệt với Arthur
      {
        heroId: 110,
        team: 1,
        x: -18 + 7 * Math.sin(t * 0.7),
        z: 22 + 5 * Math.cos(t * 0.7),
        hp: 6200 + Math.sin(t * 3) * 1200,
        maxHp: 7500
      },
      // Krixi (112): Pháp sư Mid dâng cao xả bão hoa, giằng co với Aleister
      {
        heroId: 112,
        team: 1,
        x: -4 + 7 * Math.sin(t * 0.5),
        z: -3 + 6 * Math.cos(t * 0.5),
        hp: 3900 + Math.sin(t * 1.5) * 600,
        maxHp: 4800
      },
      // Violet (120): Xạ thủ Bot đẩy đường Rồng, lăn lộn bắn tỉa
      {
        heroId: 120,
        team: 1,
        x: 12 + 6 * Math.cos(t * 0.45),
        z: -24 + 4 * Math.sin(t * 0.45),
        hp: 4100 + Math.cos(t) * 400,
        maxHp: 4500
      },
      // Butterfly (118): Đi cùng bảo kê / gank hỗ trợ Bot
      {
        heroId: 118,
        team: 1,
        x: 10 + 6 * Math.cos(t * 0.45 + 0.3),
        z: -22 + 4 * Math.sin(t * 0.45 + 0.3),
        hp: 5800 + Math.sin(t) * 300,
        maxHp: 6300
      },

      // TEAM 2 (ĐỎ):
      // Zephys (106): Đi rừng phe Đỏ, đảo đường gank Top & Bot
      {
        heroId: 106,
        team: 2,
        x: 10 + 10 * Math.sin(t * 0.4) - 4 * Math.cos(t * 0.8),
        z: -4 + 10 * Math.cos(t * 0.4) + 6 * Math.sin(t * 0.8),
        hp: 4800 + Math.cos(t * 2) * 700,
        maxHp: 5800
      },
      // Arthur (111): Đấu sĩ Top phe Đỏ đánh tay đôi Lữ Bố
      {
        heroId: 111,
        team: 2,
        x: -13 - 6 * Math.sin(t * 0.7 + 0.4),
        z: 24 - 4 * Math.cos(t * 0.7 + 0.4),
        hp: 6800 + Math.cos(t * 3) * 1100,
        maxHp: 8200
      },
      // Aleister (116): Pháp sư Mid phe Đỏ đặt ma trận khống chế
      {
        heroId: 116,
        team: 2,
        x: 3 - 6 * Math.sin(t * 0.5),
        z: 3 - 6 * Math.cos(t * 0.5),
        hp: 4300 + Math.cos(t * 1.5) * 700,
        maxHp: 5100
      },
      // Yorn (113): Xạ thủ Bot phe Đỏ xả tên từ xa
      {
        heroId: 113,
        team: 2,
        x: 18 - 5 * Math.cos(t * 0.45),
        z: -19 - 4 * Math.sin(t * 0.45),
        hp: 3900 + Math.sin(t) * 500,
        maxHp: 4600
      },
      // Mina (121): Trợ thủ chống chịu phe Đỏ đứng chắn trước Yorn
      {
        heroId: 121,
        team: 2,
        x: 15 - 5 * Math.cos(t * 0.45 + 0.3),
        z: -21 - 4 * Math.sin(t * 0.45 + 0.3),
        hp: 7900 + Math.cos(t) * 900,
        maxHp: 9100
      }
    ];

    applyFrame({
      version: 1,
      state: "battle",
      sessionId: code,
      players: simPlayers,
      towers: initialTowers,
      minions: simMinions
    });
  };

  runTick();
  setInterval(runTick, 60);
}

function connectWebSocket() {
  if (isMockCode(sessionId)) { startMockSimulation(sessionId); return; }
  if (reconnectStopped) {
    return;
  }
  if (!sessionId) {
    setStatus("Thiếu mã", "error");
    return;
  }

  const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
  const ws = new WebSocket(`wss://map.yong38.com/ws/view/${encodeURIComponent(sessionId)}`);
  setStatus("Connecting", "connecting");

  ws.addEventListener("open", () => {
    reconnectDelay = 1000;
    if (isWaitingForBattle()) {
      setStatus("Đang chờ trận đấu", "waiting");
    } else {
      setStatus("Live", "live");
    }
  });

  ws.addEventListener("message", (event) => {
    const message = JSON.parse(event.data);
    applyFrame(message.type === "frame" ? message.frame : message);
  });

  ws.addEventListener("close", () => {
    setStatus("Reconnecting", "waiting");
    verifySessionBeforeReconnect().then((shouldReconnect) => {
      if (shouldReconnect) {
        scheduleReconnect();
      }
    });
  });

  ws.addEventListener("error", () => {
    setStatus("Connection error", "offline");
    ws.close();
  });
}

window.addEventListener("resize", resizeCanvas);
setupPictureInPicture();
setupCalibrationPanel();
syncAnchorPlayerSelect();
updateAnchorStatus();
resizeCanvas();
loadSnapshot()
  .catch(() => {
    setStatus("Snapshot unavailable", "error");
  })
  .finally(connectWebSocket);

